export async function stripExifInMemory(file: File): Promise<Blob> {
  const buffer = await file.arrayBuffer();
  const view = new DataView(buffer);
  if (view.getUint16(0) !== 0xFFD8) throw new Error("UNSUPPORTED_OR_CORRUPT_SOI_HEADER");
  let offset = 2;
  const segments: ArrayBuffer[] = [buffer.slice(0, 2)];
  while (offset < buffer.byteLength) {
    const marker = view.getUint16(offset);
    if (marker === 0xFFDA) { segments.push(buffer.slice(offset)); break; }
    const length = view.getUint16(offset + 2);
    if (marker !== 0xFFE1) segments.push(buffer.slice(offset, offset + 2 + length));
    offset += 2 + length;
  }
  return new Blob(segments, { type: file.type });
}
